import React, { forwardRef, useRef } from 'react';
import Icon from 'component/common/icon';
import classnames from 'classnames';
import { NavLink, useLocation } from 'react-router-dom';
import { formatLbryUrlForWeb } from 'util/url';
import * as PAGES from 'constants/pages';
import useCombinedRefs from 'effects/use-combined-refs';
import { useAppSelector, useAppDispatch } from 'redux/hooks';
import { selectUser, selectUserVerifiedEmail } from 'redux/selectors/user';
import { selectHasChannels } from 'redux/selectors/claims';
import { doHideModal } from 'redux/actions/app';

type Props = {
  id?: string | null | undefined;
  href?: string | null | undefined;
  title?: string | null | undefined;
  label?: React.ReactNode | null | undefined;
  largestLabel?: string | null | undefined;
  icon?: string | null | undefined;
  iconRight?: string | null | undefined;
  disabled?: boolean | null | undefined;
  children?: React.ReactNode | null | undefined;
  navigate?: string | null | undefined;
  navigateTarget?: string;
  className?: string | null | undefined;
  description?: string | null | undefined;
  type?: string;
  button?: string | null | undefined;
  // primary, secondary, alt, link
  iconSize?: number;
  iconColor?: string;
  activeClass?: string;
  innerRef?: any | null | undefined;
  authSrc?: string;
  autoFocus?: boolean;
  // Events
  onClick?: ((arg0: any) => any) | null | undefined;
  onMouseEnter?: ((arg0: any) => any) | null | undefined;
  onMouseLeave?: ((arg0: any) => any) | null | undefined;
  onChange?: ((arg0: any) => any) | null | undefined;
  requiresAuth?: boolean;
  requiresChannel?: boolean;
  myref?: any;
  name?: string;
  target?: string;
  'aria-label'?: string;
  'aria-hidden'?: boolean;
  style?: React.CSSProperties;
  tabIndex?: number;
  noStyle?: boolean;
  channelId?: any;
  [key: string]: any;
};
// check if the link is for odysee.com
function isAnOdyseeLink(urlString) {
  return urlString && (urlString.indexOf('https://odysee.com') !== -1 || urlString.indexOf('http://odysee.com') !== -1);
}

// use forwardRef to allow consumers to pass refs to the button content if they want to
// flow requires forwardRef have default type arguments passed to it
const Button = forwardRef<any, Props>((props: Props, ref: any) => {
  const {
    type = 'button',
    onClick: onClickProp,
    href,
    title,
    label,
    largestLabel,
    icon,
    // This should rarely be used. Regular buttons should just use `icon`
    // `iconRight` is used for the header (home) button with the LBRY icon and external links that are displayed inline
    iconRight,
    disabled,
    children,
    navigate,
    navigateTarget,
    className,
    description,
    button,
    iconSize,
    iconColor,
    activeClass,
    requiresAuth,
    requiresChannel,
    myref,
    authSrc,
    ...otherProps
  } = props as Props & Record<string, any>;

  const dispatch = useAppDispatch();
  const location = useLocation();
  const pathname = location.pathname;

  // Only compute auth-related state when the button actually needs it.
  // This prevents every single button in the app from re-rendering on
  // unrelated Redux state changes (user, router, channels).
  const needsAuth = requiresAuth || requiresChannel;
  const emailVerified = useAppSelector((state) => (needsAuth ? selectUserVerifiedEmail(state) : false));
  const user = useAppSelector((state) => (needsAuth ? selectUser(state) : undefined));
  const hasChannels = useAppSelector((state) => (needsAuth ? selectHasChannels(state) : false));

  const disable = disabled || (user === null && requiresAuth);
  const onClick = disabled ? undefined : onClickProp;
  const combinedClassName = classnames(
    'button',
    button
      ? {
          'button--primary': button === 'primary',
          'button--secondary': button === 'secondary',
          'button--alt': button === 'alt',
          'button--inverse': button === 'inverse',
          'button--close': button === 'close',
          'button--disabled': disable,
          'button--link': button === 'link',
          'button--liquidass': button === 'liquidass',
        }
      : 'button--no-style',
    className
  );
  const innerRef = useRef(null);
  const combinedRef = useCombinedRefs(ref, innerRef, myref);
  const size = iconSize || (!label && !children) ? 18 : undefined; // Fall back to default

  // Label can be a string or object ( use title instead )
  const ariaLabel = description || (typeof label === 'string' ? label : title);
  const content = (
    <span className="button__content">
      {icon && <Icon icon={icon} iconColor={iconColor} size={iconSize} />}

      {!largestLabel && label && (
        <span dir="auto" className="button__label">
          {label}
        </span>
      )}

      {/* largestLabel is used when a single button has two different labels based on hover state */}
      {largestLabel && (
        <div
          dir="auto"
          className="button__label"
          style={{
            position: 'relative',
          }}
        >
          <div
            style={{
              position: 'relative',
              left: '50%',
              top: '50%',
              transform: `translate(-50%, 0%)`,
            }}
          >
            <span
              style={{
                visibility: 'hidden',
              }}
            >
              {largestLabel || label}
              <div
                style={{
                  position: 'absolute',
                  left: '50%',
                  top: '50%',
                  transform: `translate(-50%, -50%)`,
                }}
              >
                <span
                  style={{
                    visibility: 'visible',
                  }}
                >
                  {label}
                </span>
              </div>
            </span>
          </div>
        </div>
      )}

      {children}
      {iconRight && <Icon icon={iconRight} iconColor={iconColor} size={iconSize || size} />}
    </span>
  );

  // if it's an internal link we won't open a new tab
  const isAnInternalLink = (href || navigate) && (isAnOdyseeLink(href) || isAnOdyseeLink(navigate));

  if (href || (navigate && navigate.startsWith('http'))) {
    const finalHref = href || navigate || '';
    const cordovaHandler = (e: any) => {
      if (window.cordova && window.odysee?.functions) {
        e.preventDefault();
        if (isAnInternalLink && window.odysee.functions.history?.push) {
          const stripped = String(finalHref).replace(/^https?:\/\/[^/]+/, '');
          window.odysee.functions.history.push(stripped);
        } else if (window.odysee.functions.initBrowser) {
          window.odysee.functions.initBrowser(finalHref, 'external');
        }
      }
      if (onClick) onClick(e);
    };
    return (
      <a
        target={navigateTarget || (isAnInternalLink ? '' : '_blank')}
        rel="noopener noreferrer"
        href={finalHref}
        className={combinedClassName}
        title={title}
        onClick={cordovaHandler}
        aria-label={ariaLabel}
        disabled={disabled}
        ref={combinedRef}
        {...(otherProps as any)}
      >
        {content}
      </a>
    );
  }

  // Handle lbry:// uris passed in, or already formatted web urls
  let path = navigate;

  if (path) {
    if (path.startsWith('lbry://')) {
      path = formatLbryUrlForWeb(path);
    } else if (!path.startsWith('/')) {
      // Force a leading slash so new paths aren't appended on to the current path
      path = `/${path}`;
    }
  }

  // Try to generate a tooltip using available text and display it through
  // the 'title' mechanism, but only if it isn't being used.
  let defaultTooltip;

  if (!title) {
    if (props['aria-label']) {
      defaultTooltip = props['aria-label'];
    } else if (description) {
      defaultTooltip = description;
    }
  }

  if ((requiresAuth && !emailVerified) || (requiresChannel && !hasChannels)) {
    // requiresChannel can be used for both requiresAuth and requiresChannel,
    // since if the button requiresChannel, it also implies it requiresAuth in order to proceed
    // so using requiresChannel means: unauth users are sent to signup, auth users to create channel
    const page = !emailVerified ? PAGES.AUTH : PAGES.CHANNEL_NEW;
    let redirectUrl = `/$/${page}?redirect=${pathname}`;

    if (authSrc) {
      redirectUrl += `&src=${authSrc}`;
    }

    return (
      <NavLink
        end
        onClick={(e) => {
          e.stopPropagation();
          // in case the redirect came from a modal, it will stay open on the
          // sign up page, so close it to make the sign up form seen
          dispatch(doHideModal());
        }}
        to={redirectUrl}
        title={title || defaultTooltip}
        disabled={disable}
        className={({ isActive }) => classnames(combinedClassName, isActive && activeClass)}
        aria-label={ariaLabel}
        ref={combinedRef}
        {...(otherProps as any)}
      >
        {content}
      </NavLink>
    );
  }

  return path ? (
    <NavLink
      end
      to={path}
      title={title || defaultTooltip}
      disabled={disable}
      onClick={(e) => {
        e.stopPropagation();
        // Prevent duplicate history entries when navigating to the current page
        const currentPath = window.location.pathname + window.location.search;

        if (path === currentPath || path === window.location.pathname) {
          e.preventDefault();
        }

        if (onClick) {
          onClick(e);
        }
      }}
      className={({ isActive }) => classnames(combinedClassName, isActive && activeClass)}
      aria-label={ariaLabel}
      ref={combinedRef}
      {...(otherProps as any)}
    >
      {content}
    </NavLink>
  ) : (
    <button
      ref={combinedRef}
      title={title || defaultTooltip}
      aria-label={ariaLabel}
      className={combinedClassName}
      onClick={(e) => {
        if (onClick) {
          e.stopPropagation();
          onClick(e);
        }
      }}
      disabled={disable}
      type={type as 'button' | 'submit' | 'reset'}
      {...otherProps}
    >
      {content}
    </button>
  );
});

Button.displayName = 'Button';

export default React.memo(Button) as any;
